#include "통신규약.h"
static အင်တာနက်ကွန်ရက်ပေါက်လိပ်စာ လိပ်စာ(unsigned ဆက်သွယ်ပေါက်တန်ဖိုး) {
    အင်တာနက်ကွန်ရက်ပေါက်လိပ်စာ တန်ဖိုး = {}; တန်ဖိုး.လိပ်စာမျိုးစု = အင်တာနက်မျိုးစု;
    တန်ဖိုး.ဆက်သွယ်ပေါက်ကိန်း = ကွန်ရက်တို(ဆက်သွယ်ပေါက်တန်ဖိုး); တန်ဖိုး.အင်တာနက်လိပ်စာ.လိပ်စာတန်ဖိုး = ကွန်ရက်ကိန်းပြည့်(ပြန်လှည့်မှုလိပ်စာ); return တန်ဖိုး;
}
extern "C" int သုံးစွဲသူပရိုဂရမ်စတင်(int) {
    int ပို့အဆုံးမှတ် = အဆုံးမှတ်ဖန်တီး(အင်တာနက်မျိုးစု, ဒေတာစာကွန်ရက်ပေါက်, 0);
    int လက်ခံအဆုံးမှတ် = အဆုံးမှတ်ဖန်တီး(အင်တာနက်မျိုးစု, ဒေတာစာကွန်ရက်ပေါက်, ဒေတာစာဆက်သွယ်စည်းမျဉ်း);
    if (ပို့အဆုံးမှတ် < 0 || လက်ခံအဆုံးမှတ် < 0) return 1;
    အင်တာနက်ကွန်ရက်ပေါက်လိပ်စာ ဆိုက်ရောက်မှု = လိပ်စာ(7777), ထွက်ခွာမှု = လိပ်စာ(7778), ပို့ပြီးလိပ်စာ = {};
    ကွန်ရက်ပေါက်လိပ်စာအလျားအမျိုးပုံစံ လိပ်စာအလျား = sizeof(ပို့ပြီးလိပ်စာ);
    if (လိပ်စာချည်နှောင်(လက်ခံအဆုံးမှတ်, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု))) return 2;
    if (လိပ်စာချည်နှောင်(ပို့အဆုံးမှတ်, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု)) != -1 || အမှားကိန်း != 98) return 3;
    if (လိပ်စာချည်နှောင်(ပို့အဆုံးမှတ်, (ကွန်ရက်ပေါက်လိပ်စာ *)&ထွက်ခွာမှု, sizeof(ထွက်ခွာမှု))) return 4;
    static const char အကြောင်းအရာတန်ဖိုး[] = "한글 UDP loopback 😀";
    char ရရှိတန်ဖိုး[64] = {};
    if (ဒေတာစာဒေတာပို့(ပို့အဆုံးမှတ်, အကြောင်းအရာတန်ဖိုး, sizeof(အကြောင်းအရာတန်ဖိုး), 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု)) != sizeof(အကြောင်းအရာတန်ဖိုး)) return 5;
    if (ဒေတာစာဒေတာလက်ခံရယူ(လက်ခံအဆုံးမှတ်, (void *)အကြောင်းအရာတန်ဖိုး, sizeof(အကြောင်းအရာတန်ဖိုး), 0, 0, 0) != -1 || အမှားကိန်း != 14) return 6;
    if (ဒေတာစာဒေတာလက်ခံရယူ(လက်ခံအဆုံးမှတ်, ရရှိတန်ဖိုး, sizeof(ရရှိတန်ဖိုး), 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ပို့ပြီးလိပ်စာ, &လိပ်စာအလျား) != sizeof(အကြောင်းအရာတန်ဖိုး)) return 7;
    if (လိပ်စာအလျား != sizeof(ပို့ပြီးလိပ်စာ) || ကိရိယာအစဉ်တို(ပို့ပြီးလိပ်စာ.ဆက်သွယ်ပေါက်ကိန်း) != 7778 || ကိရိယာအစဉ်ကိန်းပြည့်(ပို့ပြီးလိပ်စာ.အင်တာနက်လိပ်စာ.လိပ်စာတန်ဖိုး) != ပြန်လှည့်မှုလိပ်စာ) return 8;
    for (unsigned အစဉ်အမှတ် = 0; အစဉ်အမှတ် < sizeof(အကြောင်းအရာတန်ဖိုး); အစဉ်အမှတ်++) if (ရရှိတန်ဖိုး[အစဉ်အမှတ်] != အကြောင်းအရာတန်ဖိုး[အစဉ်အမှတ်]) return 9;
    if (ဒေတာစာဒေတာလက်ခံရယူ(လက်ခံအဆုံးမှတ်, ရရှိတန်ဖိုး, sizeof(ရရှိတန်ဖိုး), 0, 0, 0) != -1 || အမှားကိန်း != 11) return 10;
    if (ဒေတာစာဒေတာပို့(လက်ခံအဆုံးမှတ်, ရရှိတန်ဖိုး, sizeof(အကြောင်းအရာတန်ဖိုး), 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ပို့ပြီးလိပ်စာ, sizeof(ပို့ပြီးလိပ်စာ)) != sizeof(အကြောင်းအရာတန်ဖိုး)) return 11;
    if (ဒေတာစာဒေတာလက်ခံရယူ(ပို့အဆုံးမှတ်, ရရှိတန်ဖိုး, 4, 0, 0, 0) != 4) return 12;
    if (ဒေတာစာဒေတာလက်ခံရယူ(ပို့အဆုံးမှတ်, ရရှိတန်ဖိုး, 4, 0, 0, 0) != -1 || အမှားကိန်း != 11) return 13;
    for (int အစဉ်အမှတ် = 0; အစဉ်အမှတ် < 4; အစဉ်အမှတ်++) if (ဒေတာစာဒေတာပို့(ပို့အဆုံးမှတ်, အကြောင်းအရာတန်ဖိုး, sizeof(အကြောင်းအရာတန်ဖိုး), 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု)) != sizeof(အကြောင်းအရာတန်ဖိုး)) return 14;
    if (ဒေတာစာဒေတာပို့(ပို့အဆုံးမှတ်, အကြောင်းအရာတန်ဖိုး, sizeof(အကြောင်းအရာတန်ဖိုး), 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု)) != -1 || အမှားကိန်း != 11) return 15;
    for (int အစဉ်အမှတ် = 0; အစဉ်အမှတ် < 4; အစဉ်အမှတ်++) if (ဒေတာစာဒေတာလက်ခံရယူ(လက်ခံအဆုံးမှတ်, ရရှိတန်ဖိုး, sizeof(ရရှိတန်ဖိုး), 0, 0, 0) != sizeof(အကြောင်းအရာတန်ဖိုး)) return 16;
    if (ဒေတာစာဒေတာပို့(ပို့အဆုံးမှတ်, 0, 0, 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု)) != 0 ||
        ဒေတာစာဒေတာလက်ခံရယူ(လက်ခံအဆုံးမှတ်, 0, 0, 0, 0, 0) != 0) return 21;
    ဆိုက်ရောက်မှု.အင်တာနက်လိပ်စာ.လိပ်စာတန်ဖိုး = ကွန်ရက်ကိန်းပြည့်(0x08080808);
    if (ဒေတာစာဒေတာပို့(ပို့အဆုံးမှတ်, အကြောင်းအရာတန်ဖိုး, sizeof(အကြောင်းအရာတန်ဖိုး), 0, (ကွန်ရက်ပေါက်လိပ်စာ *)&ဆိုက်ရောက်မှု, sizeof(ဆိုက်ရောက်မှု)) != -1 || အမှားကိန်း != 101) return 17;
    if (အဆုံးမှတ်ဖန်တီး(အင်တာနက်မျိုးစု, စီးကြောင်းဆက်သွယ်မှု, ဒေတာစာဆက်သွယ်စည်းမျဉ်း) != -1 || အမှားကိန်း != 93) return 18;
    လိပ်စာအလျား = sizeof(ပို့ပြီးလိပ်စာ);
    if (ကွန်ရက်ပေါက်လိပ်စာဖတ်(လက်ခံအဆုံးမှတ်, (ကွန်ရက်ပေါက်လိပ်စာ *)&ပို့ပြီးလိပ်စာ, &လိပ်စာအလျား) || ကိရိယာအစဉ်တို(ပို့ပြီးလိပ်စာ.ဆက်သွယ်ပေါက်ကိန်း) != 7777) return 19;
    if (ဖိုင်ပိတ်(လက်ခံအဆုံးမှတ်) || ဖိုင်ပိတ်(လက်ခံအဆုံးမှတ်) != -1 || အမှားကိန်း != 9) return 20;
    // 보내는곳은 열어 둔다: ထွက်ပရိုဂရမ် 시 프로세스별 socket 정리를 검사한다.
    static const char ဖြစ်သောအပြည့်အစုံ[] = "EL0 UDP LOOPBACK PASS (external network unavailable)\n";
    ဖိုင်ဒေတာရေး(1, ဖြစ်သောအပြည့်အစုံ, sizeof(ဖြစ်သောအပြည့်အစုံ) - 1);
    return 0;
}
